import { BrowserRouter, Routes, Route, Link } from "react-router-dom";

function Home() {
  return <h1>Home</h1>;
}

function About() {
  return <h1>About</h1>;
}

export function App() {
  return (
    <BrowserRouter>
      <nav><Link to="/">Home</Link> <Link to="/about">About</Link></nav>
      <Routes>
        <Route path="/" element={<Home />} />
        <Route path="/about" element={<About />} />
      </Routes>
    </BrowserRouter>
  );
}

import { useParams, Link } from "react-router-dom";

function PostDetails() {
  const { postId } = useParams<{ postId: string }>();

  if (!postId) return <p>Post ID is missing.</p>;

  return (
    <section>
      <h1>Post {postId}</h1>
      <Link to="/posts">Back to posts</Link>
    </section>
  );
}

import { Outlet } from "react-router-dom";

function AppLayout() {
  return (
    <>
      <header><strong>Study Portal</strong></header>
      <main><Outlet /></main>
    </>
  );
}

// Route configuration uses AppLayout as a parent route,
